// Do NOT remove this node.
// Without it, anyone who learns this URL can post a fake "overdue" event and
// make you message your own customers.
const crypto = require('crypto');

const SECRET = $vars.AIMUNIM_WEBHOOK_SECRET;   // Automation -> Webhooks -> Dikhayein
if (!SECRET) throw new Error('AIMUNIM_WEBHOOK_SECRET n8n variable not set');

const item   = $input.first().json;
const raw    = JSON.stringify(item.body);
const header = item.headers['x-aimunim-signature'];
if (!header) throw new Error('Missing X-AiMunim-Signature');

const parts = Object.fromEntries(header.split(',').map(kv => kv.split('=')));
const t = Number(parts.t);
if (!Number.isFinite(t)) throw new Error('Malformed signature header');

// Freshness window. The timestamp is inside the HMAC, so it cannot be edited
// to dodge this check — an old captured request stays unusable.
if (Math.abs(Math.floor(Date.now() / 1000) - t) > 300) {
  throw new Error('Signature too old — possible replay');
}

const expected = crypto.createHmac('sha256', SECRET).update(`${t}.${raw}`).digest('hex');
if (expected !== parts.v1) throw new Error('Bad signature');

return [{ json: item.body }];

// AI Munim reminder sequences ko apne aap band nahi karta — wo aapka
// business rule hai, uska nahi. Isliye doosra reminder bhejne se pehle yahan
// check karo ki payment aayi ya nahi.
//
// Static data me hum har payment.received event ka invoice_id rakhte hain
// (dekho workflow ka doosra branch).
const invoiceId = $('Verify Signature').first().json.data.invoice_id;
const paid = $getWorkflowStaticData('global').paidInvoices || {};

if (paid[invoiceId]) {
  return [];   // payment aa gayi — sequence yahin rok do
}
return $input.all();

// Remember which invoices have been settled so the reminder ladder above
// can stop. Simple and good enough; for high volume use a real store.
const d = $input.first().json.data;
if (d.invoice_id) {
  const sd = $getWorkflowStaticData('global');
  sd.paidInvoices = sd.paidInvoices || {};
  sd.paidInvoices[d.invoice_id] = true;
}
return $input.all();
